// 1. Get the target date from your specific node
const targetDateStr = $('Loop Over Items2').first().json.dateFrom;
const targetDate = new Date(targetDateStr);

// 2. Get the array of launched dates from the current incoming item
const launchDates = $input.first().json['Launched Date'];

// 3. Map over the dates and calculate the differences
const calculations = launchDates.map(dateStr => {
  const launchDate = new Date(dateStr);
  const diffDays = Math.round((targetDate - launchDate) / 86400000);

  return {
    "Launched Date": dateStr,
    "Days Since Launch": diffDays
  };
});

// 4. Return exactly ONE item containing all the data
return [{
  json: {
    "Target Date": targetDateStr,
    "Calculated Results": calculations
  }
}];

