/**
 * Leave Request Pre-Analyzer
 * --------------------------
 * Pre-analyzes leave days BEFORE the LLM evaluation.
 *
 * Outputs:
 * - daysWithFD          (numeric)
 * - daysUntilStart      (calendar days from dateFiled → dateFrom)
 * - group               "A" | "B"
 * - groupReason         human-readable reason
 * - perDayBreakdown[]   each requested day with:
 * • date, dayOfWeek, isWorkDay, isHoliday, holidayName,
 * adjacentToWeekendOrHoliday, classification ("CRITICAL"|"NON_CRITICAL"|"REST_DAY"|"HOLIDAY")
 * - summary             aggregate counts
 *
 * Usage:
 * const result = analyzeLeaveRequest({ dateFiled, dateFrom, dateTo, daysWithFD, matchingStatus, workSchedule });
 */

// ─── 2026 PH Holidays ────────────────────────────────────────────────
const PH_HOLIDAYS_2026 = [
  { date: "2026-01-01", name: "New Year's Day" },
  { date: "2026-02-17", name: "EDSA Revolution Anniversary" },
  // Feb 25 is a WORKING holiday — included but flagged
  { date: "2026-02-25", name: "People Power Anniversary (Working Holiday)", working: true },
  { date: "2026-03-16", name: "Start of Ramadan (tentative)" },
  { date: "2026-03-20", name: "Araw ng Kagitingan (moved, tentative)" },
  { date: "2026-04-02", name: "Maundy Thursday" },
  { date: "2026-04-03", name: "Good Friday" },
  { date: "2026-04-04", name: "Black Saturday" },
  { date: "2026-04-09", name: "Araw ng Kagitingan" },
  { date: "2026-05-01", name: "Labor Day" },
  { date: "2026-05-27", name: "Eid'l Fitr (tentative)" },
  { date: "2026-06-12", name: "Independence Day" },
  { date: "2026-08-14", name: "Eid'l Adha (tentative)" },
  { date: "2026-08-21", name: "Ninoy Aquino Day" },
  { date: "2026-08-31", name: "National Heroes Day" },
  { date: "2026-11-01", name: "All Saints' Day" },
  { date: "2026-11-02", name: "All Souls' Day" },
  { date: "2026-11-30", name: "Bonifacio Day" },
  { date: "2026-12-08", name: "Feast of the Immaculate Conception" },
  { date: "2026-12-24", name: "Christmas Eve" },
  { date: "2026-12-25", name: "Christmas Day" },
  { date: "2026-12-30", name: "Rizal Day" },
  { date: "2026-12-31", name: "Last Day of the Year" },
];

// Build a lookup map  →  { "2026-01-01": { name, working } }
const holidayMap = {};
PH_HOLIDAYS_2026.forEach((h) => {
  holidayMap[h.date] = { name: h.name, working: !!h.working };
});

// ─── Helpers ──────────────────────────────────────────────────────────

/** Strip HTML tags and normalize whitespace for description parsing */
function cleanHtml(html) {
  if (!html) return "";
  let text = html
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");
  text = text.replace(/<[^>]+>/g, " ");
  text = text.replace(/\s+/g, " ");
  return text.trim();
}

/** Extract a named field value from Zoho description raw HTML.
 *  The Zoho leave form renders as:
 *    <td>Field Name</td><td>:</td><td>Value</td>
 *  Parsing the HTML structure directly avoids whitespace-collapse issues
 *  that break multi-word values like "Sick Leave". */
function extractTableField(html, fieldName) {
  if (!html || !fieldName) return null;
  // Match <td>Field Name</td> <td>:</td> <td>Value</td> with flexible whitespace/attrs
  const escapedField = fieldName.replace(/\s+/g, "\\s+");
  const regex = new RegExp(
    '<td[^>]*>\\s*' + escapedField + '\\s*</td>\\s*<td[^>]*>\\s*:?\\s*</td>\\s*<td[^>]*>\\s*(.*?)\\s*</td>',
    'is'
  );
  const match = html.match(regex);
  if (!match) return null;
  // Strip any remaining inner HTML tags from the captured value
  let value = match[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/gi, ' ').trim();
  return value || null;
}

/** Normalize leave type string for comparison */
function normalizeLeaveType(lt) {
  if (!lt) return "";
  return lt.toLowerCase().replace(/[^a-z]/g, "");
}

/** Safely parse any date-ish string to standard YYYY-MM-DD */
function tryParseDateKey(input) {
  if (!input) return null;
  let s = String(input).trim();

  // Handle DD-Mon-YYYY, DD Mon YYYY, DD/Mon/YYYY
  // e.g. "14-Oct-2025", "14 October 2025", "3-Jan-2026"
  const dmy = s.match(
    /^(\d{1,2})[\s\-\/](Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)[\s\-\/](\d{4})$/i
  );
  if (dmy) {
    // Rearrange to "Oct 14, 2025" which Date() parses reliably
    s = `${dmy[2]} ${dmy[1]}, ${dmy[3]}`;
  }

  const d = new Date(s);
  if (isNaN(d.getTime())) return null;
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

/** Normalize any date-ish input to a local-midnight Date */
function toLocalDate(input) {
  const d = new Date(input);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

/** "YYYY-MM-DD" key for a Date */
function dateKey(d) {
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

/** Day-of-week label */
function dayLabel(d) {
  return d.toLocaleDateString("en-US", { weekday: "long" });
}

/** Calendar day diff (dateB − dateA) */
function dayDiff(a, b) {
  return Math.round((toLocalDate(b) - toLocalDate(a)) / 86_400_000);
}

/** Generate an inclusive date range */
function dateRange(from, to) {
  const dates = [];
  let cur = toLocalDate(from);
  const end = toLocalDate(to);
  while (cur <= end) {
    dates.push(new Date(cur));
    cur.setDate(cur.getDate() + 1);
  }
  return dates;
}

/**
 * Parse "Days with FD" field.
 * Handles formats like "59D", "59", "59 days", etc.
 * Returns numeric days or null if unparseable.
 */
function parseDaysWithFD(raw) {
  if (raw == null) return null;
  const s = String(raw).trim();
  const m = s.match(/(\d+)/);
  return m ? parseInt(m[1], 10) : null;
}

// ─── Work-Schedule Parser ─────────────────────────────────────────────
/**
 * workSchedule comes from Sprout as flat keys:
 * { mondayFrom: "09:00", mondayTo: "18:00", mondayIsRestday: false,
 * saturdayFrom: "REST DAY", saturdayIsRestday: true, ... }
 *
 * Returns a Set of weekday names (e.g. "Saturday") that are REST days.
 */
function getRestDays(workSchedule) {
  const restDays = new Set();
  if (!workSchedule) return restDays;

  const days = [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday",
  ];

  days.forEach((day) => {
    const isRestKey = `${day}IsRestday`;
    const fromKey = `${day}From`;

    // Explicit rest day flag
    if (workSchedule[isRestKey] === true) {
      restDays.add(day.charAt(0).toUpperCase() + day.slice(1)); // "Saturday"
      return;
    }

    // Fallback: if "From" is "REST DAY" or missing → rest day
    const fromVal = workSchedule[fromKey];
    if (!fromVal || fromVal === "REST DAY") {
      restDays.add(day.charAt(0).toUpperCase() + day.slice(1));
    }
  });

  return restDays;
}

// ─── Core: Is a given date a non-working day? ─────────────────────────
/**
 * A date is non-working if:
 * 1. It falls on the employee's rest day (per schedule), OR
 * 2. It is a non-working PH holiday (working: false / undefined)
 */
function isNonWorkingDay(date, restDays) {
  const dow = dayLabel(date);
  if (restDays.has(dow)) return { nonWorking: true, reason: "rest_day" };

  const key = dateKey(date);
  const hol = holidayMap[key];
  if (hol && !hol.working) return { nonWorking: true, reason: "holiday", holidayName: hol.name };

  return { nonWorking: false };
}

// ─── Core: Critical-Day Detection ────────────────────────────────────
/**
 * A CRITICAL work day is one directly adjacent (before or after) to a
 * weekend/rest-day OR a non-working holiday.
 *
 * Logic: check day-1 and day+1. If either is non-working → CRITICAL.
 */
function isCriticalDay(date, restDays) {
  const prev = new Date(date);
  prev.setDate(prev.getDate() - 1);
  const next = new Date(date);
  next.setDate(next.getDate() + 1);

  const prevNW = isNonWorkingDay(prev, restDays);
  const nextNW = isNonWorkingDay(next, restDays);

  const adjacentDays = [];
  if (prevNW.nonWorking) adjacentDays.push({ direction: "before", ...prevNW });
  if (nextNW.nonWorking) adjacentDays.push({ direction: "after", ...nextNW });

  return {
    isCritical: adjacentDays.length > 0,
    adjacentNonWorkingDays: adjacentDays,
  };
}

// ─── Main Analyzer ───────────────────────────────────────────────────
/**
 * @param {Object} input
 * @param {string|Date} input.dateFiled    – when the leave was filed
 * @param {string|Date} input.dateFrom     – leave start
 * @param {string|Date} input.dateTo       – leave end
 * @param {string|number} input.daysWithFD – e.g. "59D"
 * @param {string} input.matchingStatus    – Sprout matching status
 * @param {Object} input.workSchedule      – Sprout workSchedule obj
 * @param {string} input.leaveType         – e.g. "Sick Leave", "Vacation Leave"
 * @returns {Object} pre-analysis result
 */
function analyzeLeaveRequest({
  dateFiled,
  dateFrom,
  dateTo,
  daysWithFD,
  matchingStatus,
  workSchedule,
  leaveType,
  zohoSubject,
  zohoDescription, // Now taking description instead of createdTime
  zohoStatus,
}) {
  // ── 1. Parse initial Days with FD ──────────────────────────────────
  const initialFdDays = parseDaysWithFD(daysWithFD);

  // ── 2. Days until start ────────────────────────────────────────────
  const daysUntilStart = dayDiff(dateFiled, dateFrom);

  // ── 3. Combined Days with FD (tenure at leave start) ───────────────
  const combinedFdDays = (initialFdDays !== null ? initialFdDays : 0) + daysUntilStart;

  // ── 4. Group determination ─────────────────────────────────────────
  //   Group A: < 60 combined days with FD  OR  status is "Unmatched"
  //   Group B: >= 60 combined days with FD AND matched
  const isUnmatched =
    matchingStatus &&
    matchingStatus.toLowerCase().includes("unmatched");

  let group, groupReason;
  if (isUnmatched) {
    group = "A";
    groupReason = `[${leaveType || "UNKNOWN"}] Status is Unmatched → must use Leave Request Form + Zoho`;
  } else if (initialFdDays === null) {
    group = "UNKNOWN";
    groupReason = `[${leaveType || "UNKNOWN"}] Could not parse Days with FD`;
  } else if (combinedFdDays < 60) {
    group = "A";
    groupReason = `[${leaveType || "UNKNOWN"}] Combined Days with FD (${combinedFdDays} = ${initialFdDays} + ${daysUntilStart} until start) is under 60 → Leave Request Form + Zoho required`;
  } else {
    group = "B";
    groupReason = `[${leaveType || "UNKNOWN"}] Combined Days with FD (${combinedFdDays} = ${initialFdDays} + ${daysUntilStart} until start) is 60+ → standard Sprout leave + FD approval`;
  }

  // ── 5. Zoho Ticket Validation ───────────────────────────────────────
  let zoho = {
    hasTicket: !!(zohoSubject || zohoDescription || zohoStatus),
    subjectValid: false,
    startDateMatches: false,
    endDateMatches: false,
    leaveTypeMatches: false,
    zohoStartDate: null,
    zohoEndDate: null,
    zohoLeaveType: null,
    statusType: zohoStatus || null,
    isValid: false,
    issues: [],
  };

  // ── Always extract dates AND leave type from Zoho description (regardless of group) ──
  if (zoho.hasTicket && zohoDescription) {
    // Parse directly from raw HTML table structure for reliable multi-word extraction
    const rawStartDate = extractTableField(zohoDescription, "Start Date");
    const rawEndDate   = extractTableField(zohoDescription, "End Date");
    if (rawStartDate) {
      zoho.zohoStartDate = tryParseDateKey(rawStartDate);
    }
    if (rawEndDate) {
      zoho.zohoEndDate = tryParseDateKey(rawEndDate);
    }
    // Extract Leave Type from Zoho description table
    zoho.zohoLeaveType = extractTableField(zohoDescription, "Leave Type");
  }

  // ── Always check subject (regardless of group) ──
  if (zoho.hasTicket && zohoSubject && zohoSubject.toLowerCase().includes("leave request")) {
    zoho.subjectValid = true;
  }

  // ── Always check date matches and leave type match against Sprout data ──
  const expectedDateFrom = tryParseDateKey(dateFrom);
  const expectedDateTo = tryParseDateKey(dateTo);

  if (zoho.hasTicket) {
    if (zoho.zohoStartDate && zoho.zohoStartDate === expectedDateFrom) {
      zoho.startDateMatches = true;
    }
    if (zoho.zohoEndDate && zoho.zohoEndDate === expectedDateTo) {
      zoho.endDateMatches = true;
    }
    // Compare Zoho leave type against Sprout leave type
    if (zoho.zohoLeaveType && leaveType &&
        normalizeLeaveType(zoho.zohoLeaveType) === normalizeLeaveType(leaveType)) {
      zoho.leaveTypeMatches = true;
    }
  }

  if (group === "A") {
    if (!zoho.hasTicket) {
      zoho.issues.push("No Zoho ticket found");
    } else {
      if (!zoho.subjectValid) {
        zoho.issues.push(`Zoho subject does not contain 'leave request' (got: "${zohoSubject || ""}")`);
      }

      if (!zoho.zohoStartDate) {
        zoho.issues.push("Zoho ticket description is missing Start Date");
      } else if (!zoho.startDateMatches) {
        zoho.issues.push(`Zoho Start Date (${zoho.zohoStartDate || "null"}) does not match leave Date From (${expectedDateFrom || "null"})`);
      }

      if (!zoho.zohoEndDate) {
        zoho.issues.push("Zoho ticket description is missing End Date");
      } else if (!zoho.endDateMatches) {
        zoho.issues.push(`Zoho End Date (${zoho.zohoEndDate || "null"}) does not match leave Date To (${expectedDateTo || "null"})`);
      }

      // Validate Leave Type match
      if (!zoho.zohoLeaveType) {
        zoho.issues.push("Zoho ticket description is missing Leave Type");
      } else if (!zoho.leaveTypeMatches) {
        zoho.issues.push(`Zoho Leave Type ("${zoho.zohoLeaveType}") does not match Sprout Leave Type ("${leaveType || "UNKNOWN"}")`);
      }

      zoho.isValid = zoho.hasTicket && zoho.subjectValid && zoho.startDateMatches && zoho.endDateMatches && zoho.leaveTypeMatches;
    }
  } else {
    zoho.isValid = true; // Not required for Group B, effectively "valid" for bypass
    zoho.issues.push("Not applicable for Group B");
  }

  // ── Effective Leave Type ────────────────────────────────────────────
  // Sprout's leaveTypeName is the source of truth for all routing decisions.
  // The Zoho description's Leave Type must MATCH Sprout's — if it doesn't,
  // it's flagged as a validation issue (mismatch).
  const effectiveLeaveType = leaveType || "UNKNOWN";
  const leaveTypeMismatch = zoho.zohoLeaveType && leaveType &&
    normalizeLeaveType(zoho.zohoLeaveType) !== normalizeLeaveType(leaveType);


  // ── 4. Per-day breakdown ───────────────────────────────────────────
  const restDays = getRestDays(workSchedule);
  const leaveDates = dateRange(dateFrom, dateTo);

  const perDayBreakdown = leaveDates.map((d) => {
    const key = dateKey(d);
    const dow = dayLabel(d);
    const nw = isNonWorkingDay(d, restDays);
    const hol = holidayMap[key] || null;

    let classification;
    if (nw.nonWorking && nw.reason === "rest_day") {
      classification = "REST_DAY";
    } else if (nw.nonWorking && nw.reason === "holiday") {
      classification = "HOLIDAY";
    } else {
      // It's a working day — check if critical
      const crit = isCriticalDay(d, restDays);
      classification = crit.isCritical ? "CRITICAL" : "NON_CRITICAL";
    }

    // Build detail object
    const entry = {
      date: key,
      dayOfWeek: dow,
      isWorkDay: !nw.nonWorking,
      isHoliday: !!hol,
      holidayName: hol ? hol.name : null,
      isWorkingHoliday: hol ? !!hol.working : false,
      classification,
    };

    // For critical days, attach adjacency info
    if (classification === "CRITICAL") {
      const crit = isCriticalDay(d, restDays);
      entry.adjacentNonWorkingDays = crit.adjacentNonWorkingDays.map((a) => ({
        direction: a.direction,
        reason: a.reason,
        detail: a.holidayName || a.reason,
      }));
    }

    return entry;
  });

  // ── 5. Summary ─────────────────────────────────────────────────────
  const totalDays = perDayBreakdown.length;
  const workDays = perDayBreakdown.filter((d) => d.isWorkDay).length;
  const criticalDays = perDayBreakdown.filter(
    (d) => d.classification === "CRITICAL"
  ).length;
  const nonCriticalDays = perDayBreakdown.filter(
    (d) => d.classification === "NON_CRITICAL"
  ).length;
  const restDayCount = perDayBreakdown.filter(
    (d) => d.classification === "REST_DAY"
  ).length;
  const holidayCount = perDayBreakdown.filter(
    (d) => d.classification === "HOLIDAY"
  ).length;

  const hasCriticalDay = criticalDays > 0;

  // ── 7. Sick Leave Med Cert Requirement ──────────────────────────────
  // Use effectiveLeaveType (Zoho description preferred) for all routing
  const isSickLeave = effectiveLeaveType &&
    effectiveLeaveType.toLowerCase().includes("sick");

  let sickLeave = {
    route: "N/A",
    medCertRequired: false,
    reason: "N/A",
  };

  if (isSickLeave) {
    if (group === "A") {
      sickLeave.route = "ZOHO_ALLOCATION";
      sickLeave.medCertRequired = "N/A";
      sickLeave.reason = `[${effectiveLeaveType}] Group A → route through Leave Request Form + Zoho (med cert matrix does not apply)`;
    } else if (group === "B") {
      if (hasCriticalDay) {
        sickLeave.medCertRequired = true;
        sickLeave.reason = `[${effectiveLeaveType}] Critical working day detected (${criticalDays} critical day(s)) → medical certificate REQUIRED for 1+ days`;
      } else if (workDays >= 3) {
        sickLeave.medCertRequired = true;
        sickLeave.reason = `[${effectiveLeaveType}] Non-critical days only, but ${workDays} working days (3+) → medical certificate REQUIRED`;
      } else {
        sickLeave.medCertRequired = false;
        sickLeave.reason = `[${effectiveLeaveType}] Non-critical days only, ${workDays} working day(s) (1-2) → NO medical certificate needed (per HR Handbook)`;
      }
      sickLeave.route = "MED_CERT_MATRIX";
    }
  }

  // ── 8. Auto-Decision ───────────────────────────────────────────────
  // Pre-determine if the request can be auto-approved/rejected
  // or needs further human/LLM review
  const isVacationLeave = effectiveLeaveType &&
    effectiveLeaveType.toLowerCase().includes("vacation");
  const twoWeeksNoticeMet = daysUntilStart >= 14;

  let autoDecision, autoDecisionReason;

  if (group === "A") {
