      autoDecision = "Resubmit";
      autoDecisionReason = `[${effectiveLeaveType}] -Failure to submit leave form in ZOHO. Kindly resubmit in Sprout, then submit a leave form in Zoho: https://forms.zohopublic.com/outsourceddoers2/form/LeaveRequestTrainingNesting/formperma/CzOtZrb4dJdW_iGXV20nxK8iM1n7UViGgei6wgiOmOU`;
