      // 2 weeks notice met + non-critical days → auto-approve
      autoDecision = "AUTO_APPROVED";
      autoDecisionReason = `[${effectiveLeaveType}] Group B, 2-week advance notice met (${daysUntilStart} days), non-critical day(s) only → auto-approved`;
    } else if (!twoWeeksNoticeMet) {
      // Late filing → needs review for exceptions
      autoDecision = "NEEDS_REVIEW";
      autoDecisionReason = `[${effectiveLeaveType}] Group B, advance notice NOT met (${daysUntilStart} days, need 14) → must check for valid exception (bereavement, emergency, etc.)`;
    } else {
      // 2 weeks met but has critical days → needs FD approval validation
      autoDecision = "NEEDS_REVIEW";
      autoDecisionReason = `[${effectiveLeaveType}] Group B, 2-week notice met but includes critical day(s) → requires FD approval screenshot validation`;
    }

  } else if (group === "B") {
    // Other leave types Group B: needs FD approval doc
    autoDecision = "NEEDS_REVIEW";
    autoDecisionReason = `[${effectiveLeaveType}] Group B → requires FD approval screenshot validation`;

  } else {
    autoDecision = "NEEDS_REVIEW";
    autoDecisionReason = `[${effectiveLeaveType}] Group could not be determined → manual review required`;
  }

  return {
    // ── Meta ─────────────────────────────────────────────────────────
    Name:             $('Start').item.json.Name,
    leaveType:        effectiveLeaveType,
    sproutLeaveType:  leaveType || "UNKNOWN",
    zohoLeaveType:    zoho.zohoLeaveType || null,
    leaveTypeMismatch: !!leaveTypeMismatch,
    initialDaysWithFD: initialFdDays,
    daysUntilStart,
    combinedDaysWithFD: combinedFdDays,
    dateFiled:        dateKey(toLocalDate(dateFiled)),
    dateFrom:         dateKey(toLocalDate(dateFrom)),
    dateTo:           dateKey(toLocalDate(dateTo)),

    // ── Routing ──────────────────────────────────────────────────────
    group,
    groupReason,

    // ── Auto Decision ────────────────────────────────────────────────
    autoDecision,
    autoDecisionReason,

    // ── Zoho Validation (Always returned to prevent undefined errors in n8n) ──
    zoho,

    // ── Sick Leave Analysis (Always returned) ───────
    sickLeave,

    // ── Day-level detail ─────────────────────────────────────────────
    perDayBreakdown,

    // ── Aggregates ───────────────────────────────────────────────────
    summary: {
      totalCalendarDays: totalDays,
      workingDays: workDays,
      criticalDays,
      nonCriticalDays,
      restDays: restDayCount,
      holidays: holidayCount,
      hasCriticalDay,
      overallDayType: hasCriticalDay ? "CRITICAL" : "NON_CRITICAL",
    },
  };
}

